import re
from datetime import date

_MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

_ORD = r"(?:st|nd|rd|th)?"


def _iso(year: int, month: int, day: int) -> str:
    try:
        return date(year, month, day).isoformat()
    except ValueError:
        return "INVALID"


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    t = re.sub(r"\s+", " ", s.strip())
    if not t:
        return "INVALID"

    # Year-first numeric: YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD (separator must be consistent)
    m = re.fullmatch(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})", t)
    if m:
        return _iso(int(m.group(1)), int(m.group(3)), int(m.group(4)))

    # Compact: YYYYMMDD
    m = re.fullmatch(r"(\d{4})(\d{2})(\d{2})", t)
    if m:
        return _iso(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    # Day-first numeric: DD/MM/YYYY, DD-MM-YYYY, DD.MM.YYYY (ambiguous numeric dates read day-first)
    m = re.fullmatch(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4})", t)
    if m:
        return _iso(int(m.group(4)), int(m.group(3)), int(m.group(1)))

    # "5 March 2024", "5th Mar. 2024", "5-March-2024"
    m = re.fullmatch(
        rf"(\d{{1,2}}){_ORD}[\s\-]+([A-Za-z]+)\.?,?[\s\-]+(\d{{4}})", t
    )
    if m:
        month = _MONTHS.get(m.group(2).lower())
        if month:
            return _iso(int(m.group(3)), month, int(m.group(1)))
        return "INVALID"

    # "March 5, 2024", "Mar 5th 2024"
    m = re.fullmatch(
        rf"([A-Za-z]+)\.?[\s\-]+(\d{{1,2}}){_ORD},?[\s\-]+(\d{{4}})", t
    )
    if m:
        month = _MONTHS.get(m.group(1).lower())
        if month:
            return _iso(int(m.group(3)), month, int(m.group(2)))
        return "INVALID"

    return "INVALID"

"""Normalize a messy date string to ISO 'YYYY-MM-DD', or return 'INVALID'.

Standard library only. Ambiguous numeric dates are read day-first, falling back
to month-first when day-first is not a valid calendar date.
"""

import re
from datetime import date

_MONTHS = ["january", "february", "march", "april", "may", "june", "july",
           "august", "september", "october", "november", "december"]
_ORD = r"(?:st|nd|rd|th)?"
_WEEKDAY = r"^(?:mon|tue|wed|thu|fri|sat|sun)[a-z]*\.?,?\s+"


def _iso(y, m, d):
    try:
        return date(y, m, d).isoformat()
    except ValueError:
        return "INVALID"


def _month(name):
    n = name.lower().rstrip(".")
    if len(n) < 3:
        return None
    return next((i for i, full in enumerate(_MONTHS, 1) if full.startswith(n)), None)


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"
    t = re.sub(_WEEKDAY, "", s.strip(), flags=re.I)

    if m := re.fullmatch(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})", t):
        return _iso(int(m[1]), int(m[3]), int(m[4]))
    if m := re.fullmatch(r"(\d{4})(\d{2})(\d{2})", t):
        return _iso(*map(int, m.groups()))
    if m := re.fullmatch(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4})", t):
        a, b, y = int(m[1]), int(m[3]), int(m[4])
        for mo, d in ((b, a), (a, b)):  # day-first preferred
            r = _iso(y, mo, d)
            if r != "INVALID":
                return r
        return "INVALID"
    if m := re.fullmatch(r"([A-Za-z]+)\.?[\s-]+(\d{1,2})" + _ORD + r",?[\s-]+(\d{4})", t):
        mo = _month(m[1])
        return _iso(int(m[3]), mo, int(m[2])) if mo else "INVALID"
    if m := re.fullmatch(r"(\d{1,2})" + _ORD + r"(?:\s+of)?[\s-]+([A-Za-z]+)\.?,?[\s-]+(\d{4})", t):
        mo = _month(m[2])
        return _iso(int(m[3]), mo, int(m[1])) if mo else "INVALID"
    return "INVALID"

import re
import datetime

_FULL_MONTHS = {
    "january": 1, "february": 2, "march": 3, "april": 4,
    "may": 5, "june": 6, "july": 7, "august": 8,
    "september": 9, "october": 10, "november": 11, "december": 12,
}
_ABBR_MONTHS = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "sept": 9, "oct": 10, "nov": 11, "dec": 12,
}

_ORDINAL = re.compile(r"(\d{1,2})(st|nd|rd|th)\b", re.IGNORECASE)


def _month_num(word):
    w = word.lower().rstrip(".")
    if w in _FULL_MONTHS:
        return _FULL_MONTHS[w]
    return _ABBR_MONTHS.get(w)


def _build(year, month, day):
    if month is None:
        return None
    try:
        return datetime.date(year, month, day).isoformat()
    except (ValueError, TypeError):
        return None


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    t = " ".join(s.strip().split())
    if not t:
        return "INVALID"
    t = _ORDINAL.sub(r"\1", t)

    result = None

    # ISO-like: YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD (separator must be consistent)
    m = re.fullmatch(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})", t)
    if m:
        result = _build(int(m.group(1)), int(m.group(3)), int(m.group(4)))

    # Numeric day-first: DD/MM/YYYY, DD-MM-YYYY, DD.MM.YYYY
    if result is None:
        m = re.fullmatch(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4})", t)
        if m:
            result = _build(int(m.group(4)), int(m.group(3)), int(m.group(1)))

    # Month name, month first: "Nov 31 2022", "November 31, 2022"
    if result is None:
        m = re.fullmatch(r"([A-Za-z]+)\.?,?\s+(\d{1,2}),?\s+(\d{4})", t)
        if m:
            result = _build(int(m.group(3)), _month_num(m.group(1)), int(m.group(2)))

    # Month name, day first: "31 Nov 2022", "31-Nov-2022", "31 November, 2022"
    if result is None:
        m = re.fullmatch(r"(\d{1,2})[\s-]+([A-Za-z]+)\.?,?[\s-]+(\d{4})", t)
        if m:
            result = _build(int(m.group(3)), _month_num(m.group(2)), int(m.group(1)))

    # Year first with month name: "2022 Nov 31", "2022-Nov-31"
    if result is None:
        m = re.fullmatch(r"(\d{4})[\s-]+([A-Za-z]+)\.?[\s-]+(\d{1,2})", t)
        if m:
            result = _build(int(m.group(1)), _month_num(m.group(2)), int(m.group(3)))

    return result if result is not None else "INVALID"

import re
from datetime import date

_ISO = re.compile(r"([0-9]{4})([-/.])([0-9]{1,2})\2([0-9]{1,2})")
_NUM_DMY = re.compile(r"([0-9]{1,2})([-/.])([0-9]{1,2})\2([0-9]{4})")
_DMY = re.compile(
    r"([0-9]{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]+)\.?,?\s+([0-9]{4})", re.IGNORECASE
)
_MDY = re.compile(
    r"([A-Za-z]+)\.?\s+([0-9]{1,2})(?:st|nd|rd|th)?,?\s+([0-9]{4})", re.IGNORECASE
)
# Optional leading weekday (full or abbreviated), e.g. "Monday, 3 Feb 2020".
_WEEKDAY_PREFIX = re.compile(
    r"^(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday"
    r"|mon|tues|tue|wed|thurs|thur|thu|fri|sat|sun)\.?,?\s+",
    re.IGNORECASE,
)

# Exact month names and accepted abbreviations. Anything else is rejected.
_MONTH_NAMES = {
    "january": 1, "jan": 1,
    "february": 2, "feb": 2,
    "march": 3, "mar": 3,
    "april": 4, "apr": 4,
    "may": 5,
    "june": 6, "jun": 6,
    "july": 7, "jul": 7,
    "august": 8, "aug": 8,
    "september": 9, "sept": 9, "sep": 9,
    "october": 10, "oct": 10,
    "november": 11, "nov": 11,
    "december": 12, "dec": 12,
}


def _month(name: str) -> int:
    return _MONTH_NAMES.get(name.lower(), 0)


def _build(year, month, day) -> str:
    try:
        return date(int(year), int(month), int(day)).isoformat()
    except (ValueError, TypeError):
        return "INVALID"


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"
    s = " ".join(s.split())  # trim and collapse internal whitespace
    s = _WEEKDAY_PREFIX.sub("", s, count=1)
    if m := _ISO.fullmatch(s):
        return _build(m[1], m[3], m[4])
    if m := _NUM_DMY.fullmatch(s):  # ambiguous numeric dates are day-first
        return _build(m[4], m[3], m[1])
    if m := _DMY.fullmatch(s):
        return _build(m[3], _month(m[2]), m[1])
    if m := _MDY.fullmatch(s):
        return _build(m[3], _month(m[1]), m[2])
    return "INVALID"
